alter table public.stores add column if not exists state text not null default '', add column if not exists city text not null default '', add column if not exists latitude double precision, add column if not exists longitude double precision;
alter table public.stores add constraint stores_coordinates_valid check ((latitude is null and longitude is null) or (latitude is not null and longitude is not null and latitude between -90 and 90 and longitude between -180 and 180));
